function renderContracts(){const contracts=state.contracts.filter(c=>c.status!=='Cancelled'&&!c.cancelled);document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Sales Contracts</h2><div class="metaText">Open any section directly to amend a contract. Final validation still runs before Save / Print.</div></div><div class="spacer"></div><button class="btn green" id="newContract">+ NEW SALES CONTRACT</button></div><div class="tableWrap"><table class="table"><thead><tr><th>Ref</th><th>Date</th><th>Buyer</th><th>Product</th><th>Qty M.TONS</th><th>Payment</th><th>Status</th><th>Actions</th></tr></thead><tbody>${contracts.map(c=>`<tr><td>${esc(c.ref)}</td><td>${fmt(c.date)}</td><td>${esc(customer(c.customerId)?.name||c.customer||'')}</td><td>${esc(c.product)}</td><td>${num(c.qty).toFixed(3)}</td><td>${esc(PAYMENT_LABELS[c.paymentCode]||c.paymentText||'')}</td><td>${esc(c.status)}</td><td><div class="rowActions"><button class="btn small soft" data-contract="${esc(c.id)}">${!c.issued&&c.status==='Draft'?'Continue Draft':'Open / Amend'}</button>${!state.shipments.some(s=>s.kind!=='lot'&&s.contractRef===c.ref)?`<button class="btn small green" data-start-shipment="${esc(c.id)}">Start Shipment</button>`:''}<button class="btn small red" data-cancel-contract="${esc(c.id)}">Cancel</button></div></td></tr>`).join('')}</tbody></table></div></div>`;document.getElementById('newContract').onclick=()=>startContract();document.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>openContract(b.dataset.contract));document.querySelectorAll('[data-start-shipment]').forEach(b=>b.onclick=()=>startShipmentFromContract(b.dataset.startShipment));document.querySelectorAll('[data-cancel-contract]').forEach(b=>b.onclick=()=>cancelContract(b.dataset.cancelContract))}
function restartShipmentData__legacy_v0(contractId){const c=state.contracts.find(x=>x.id===contractId);if(!c)return null;const existing=state.shipments.find(s=>s.kind!=='lot'&&s.contractRef===c.ref);if(existing)return existing;const p=makeShipment(c);state.shipments.push(p);c.status=c.received?'Contract Received':'Awaiting Customer Confirmation';return p}
async function startShipmentFromContract(contractId){
 const c=state.contracts.find(row=>row.id===contractId);
 if(!c||c.cancelled||c.status==='Cancelled')return;
 const buttons=[...document.querySelectorAll('[data-start-shipment],[data-start-contract]')].filter(button=>button.dataset.startShipment===contractId||button.dataset.startContract===contractId);
 buttons.forEach(button=>button.disabled=true);
 try{
  const existed=state.shipments.some(row=>row.kind!=='lot'&&row.contractRef===c.ref);
  const p=restartShipmentData(contractId);
  if(!p)return;
  if(!existed)audit('Shipment','Started from retained Sales Contract',p.contractRef);
  const shared=window.TT_SHARED_SYNC;
  if(!shared?.saveNow)throw new Error('Shared server saving is unavailable.');
  await shared.saveNow();
  currentShipmentId=p.id;view='shipments';activeWorkspace='';renderShipmentWorkspace();
 }catch(error){showExportSaveError((error.message||'The shipment was not saved.')+' Retry Start Shipment before continuing.',buttons[0]);buttons.forEach(button=>button.disabled=false)}
}
