function cancelContract(id){const index=state.contracts.findIndex(x=>x.id===id);if(index<0)return;const c=state.contracts[index],process=state.shipments.find(s=>s.kind!=='lot'&&s.contractRef===c.ref);if(process&&contractHasDownstream(c))return alert('This contract already has issued downstream work. Delete or reverse that shipment work before cancelling the contract.');const reason=requiredReason('Mandatory reason for cancelling '+c.ref+':');if(!reason)return;const ref=c.ref,doomedIds=new Set(state.shipments.filter(s=>s.contractRef===ref||s.parentId===process?.id).map(s=>s.id));state.shipments=state.shipments.filter(s=>!doomedIds.has(s.id));for(const key of ['newExportBags','productionInstructions','exportLoading'])state.millSync[key]=(state.millSync[key]||[]).filter(row=>row.contractRef!==ref);state.contracts.splice(index,1);audit('Sales Contract','Cancelled and removed; reference released',`${ref} · ${reason}`);renderContracts()}
