 const paymentControl=isTG?`<div class="field full"><label>Payment Terms</label><select id="cuPaymentTerms">${['ADV100','CAD100','ADV_CAD'].map(code=>`<option value="${ttDirectCustomsPaymentLabel(code)}" data-code="${code}" ${code===x.customsPaymentCode?'selected':''}>${ttDirectCustomsPaymentLabel(code)}</option>`).join('')}</select></div>`:'';
 d.innerHTML=`<div class="section"><h3>CUSTOMS DOCUMENTS</h3><div class="notice">Custom Invoice is the controlling source. For a TG shipment, Customs currency is independent from the customer Sales Contract currency and controls FI selection and Pakistan-side Customs documents. The saved Customs Invoice number flows to every TG Pakistan-pack document.</div><div class="grid3">${isTG?`<div class="field"><label>Direct Shipment — Pakistan Exporter / Letterhead</label><select id="cuExporter"><option value="TTI" ${pakistanExporterKey(s)==='TTI'?'selected':''}>${esc(SELLERS.TTI)}</option><option value="BRM" ${pakistanExporterKey(s)==='BRM'?'selected':''}>${esc(SELLERS.BRM)}</option></select></div>`:''}<div class="field"><label>Importer details to show</label><select id="cuImporterChoice">${partyOptions.map(option=>`<option value="${esc(option.value)}" ${partyChoice===option.value?'selected':''}>${esc(option.label)}</option>`).join('')}</select></div><div class="field"><label>Invoice No.</label><input id="cuNo" value="${esc(x.invoiceNo||c.ref)}"></div><div class="field"><label>Date</label><input id="cuDate" type="date" value="${x.date||TODAY()}"></div><div class="field"><label>Currency${isTG?' — Customs only':''}</label><input id="cuCurrency" value="${esc(x.currency)}" ${isTG?'':'readonly'}></div><div class="field"><label>${isTG?'Pakistan Exporter → TG Rate / MT':c.incoterm+' Rate / MT (from Contract)'}</label><input id="cuRate" type="number" step=".01" value="${isTG?num(x.rate):num(unitRate(c.packings[0]||{},c))}" ${isTG?'':'readonly'}></div><div class="field"><label>Quantity M.TONS</label><input readonly value="${t.mt.toFixed(3)}"></div><div class="field"><label>Invoice Value</label><input id="cuInvoiceValue" readonly value="${money(invoiceValue,x.currency)}"></div><div class="field"><label>FI Allocated</label><input id="cuFIAllocated" readonly value="${money(fiValue,x.currency)}"></div><div class="field"><label>Open Account / Balance</label><input id="cuOpenAccount" readonly value="${openValue.toFixed(2)}"></div><div class="field full"><label>Select FI</label><div class="grid3"><select id="cuFISelect"></select><input id="cuFIAvailable" readonly placeholder="FI available balance"><input id="cuFIUse" type="number" step=".01" min="0" placeholder="Amount to utilise for this lot"></div><button class="btn small green" id="addCustomsFI" type="button">ADD FI ALLOCATION</button></div><div class="field full"><label>Current FI allocations</label><div class="tableWrap"><table class="table"><thead><tr><th>FI</th><th>Bank</th><th>Currency / Amount</th><th></th></tr></thead><tbody>${x.fiAllocations.map(row=>`<tr><td>${esc(row.number)}</td><td>${esc(row.bank||'')}</td><td>${money(row.amount,row.currency||x.currency)}</td><td><button class="btn small red" data-customs-fi-reverse="${esc(row.allocationId||'')}">Reverse</button></td></tr>`).join('')||'<tr><td colspan="4">No FI allocated.</td></tr>'}</tbody></table></div></div>${paymentControl}<div class="field"><label>HS Code</label><input id="cuHS" value="${esc(x.hsCode)}"></div><div class="field"><label>Shipper Bank</label><select id="cuBank"><option value="">Select shipper bank</option>${bankRows.map(row=>`<option value="${esc(row[4]||'')}" data-iban="${esc(row[9]||'')}" ${String(row[4]||'')===String(x.bank||'')?'selected':''}>${esc(row[4]||'Bank')}${row[9]?` · ${esc(row[9])}`:''}</option>`).join('')}</select></div><div class="field"><label>IBAN</label><input id="cuIBAN" readonly value="${esc(x.iban||ttCustomsBankRow(s,c)?.[9]||'')}"></div><div class="field full"><label>Description</label><textarea id="cuDesc">${esc(x.description)}</textarea><div class="metaText">Defaults from the current Sales Contract. A Customs-only amendment never rewrites the Sales Contract.</div></div></div><div id="customsInlineError" class="notice bad customsInlineError hidden"></div><div class="toolbar"><div class="spacer"></div><button class="btn navy" id="saveCustoms">SAVE CUSTOMS MASTER</button></div></div><div class="section"><h3>CUSTOMS PDF OUTPUT</h3><div class="toolbar"><button class="btn green" id="printCustomInvoice">Custom Invoice</button><button class="btn green" id="printCustomPacking">Custom Packing List</button><button class="btn green" id="printPhyto">Phytosanitary Invoice</button></div></div>`;
 const descriptionField=d.querySelector('#cuDesc')?.closest('.field'),phytoFields=document.createElement('div');phytoFields.className='grid2 full phytoNumberFields';phytoFields.innerHTML=`<div class="field"><label>TC NUMBER — Phytosanitary Invoice only</label><input id="cuTCNumber" value="${esc(x.tcNumber||'')}"></div><div class="field"><label>EC NUMBER — Phytosanitary Invoice only</label><input id="cuECNumber" value="${esc(x.ecNumber||'')}"></div>`;descriptionField?.before(phytoFields);d.querySelector('#cuTCNumber').oninput=event=>{x.tcNumber=event.target.value.trim()};d.querySelector('#cuECNumber').oninput=event=>{x.ecNumber=event.target.value.trim()};
 if(isTG){const input=d.querySelector('#cuCurrency'),box=document.createElement('div');box.className='managedSelectBox customsCurrencyManager';box.innerHTML=`<select id="cuCurrency">${ttActiveOptions('currency').map(value=>`<option value="${esc(value)}" ${value===x.currency?'selected':''}>${esc(value)}</option>`).join('')}<option value="__ADD_NEW__">+ Add Currency</option></select><button type="button" class="optionMinus" id="deleteCustomsCurrency" aria-label="Delete selected currency">−</button>`;input.replaceWith(box)}
 const currencyInput=d.querySelector('#cuCurrency'),rateInput=d.querySelector('#cuRate'),fiSelect=d.querySelector('#cuFISelect'),fiAvailable=d.querySelector('#cuFIAvailable'),fiUse=d.querySelector('#cuFIUse'),openInput=d.querySelector('#cuOpenAccount'),payment=d.querySelector('#cuPaymentTerms');
 const selectedCurrency=()=>String(currencyInput.value||c.currency||'USD').trim().toUpperCase();
 const eligible=()=>customsEligibleFIs(s,c);
 const drawFIs=()=>{const rows=eligible();fiSelect.innerHTML='<option value="">Select FI</option>'+rows.map(row=>`<option value="${esc(row.id)}">${esc(row.number)} · available ${money(num(row.value)-fiUsed(row),row.currency)}</option>`).join('')+'<option value="__ADD_FI__">+ Add FI</option>';fiAvailable.value=''};
 const recalc=()=>{const value=customsInvoiceValue(s,c,num(rateInput.value)),allocated=x.fiAllocations.reduce((sum,row)=>sum+num(row.amount),0),code=isTG?(payment.selectedOptions[0]?.dataset.code||'CAD100'):'';d.querySelector('#cuInvoiceValue').value=money(value,selectedCurrency());d.querySelector('#cuFIAllocated').value=money(allocated,selectedCurrency());if(isTG||x.openAccount==null||!x.saved)openInput.value=(code==='ADV100'?0:Math.max(0,value-allocated)).toFixed(2)};
 drawFIs();recalc();
 if(isTG)currencyInput.onchange=()=>{if(currencyInput.value==='__ADD_NEW__'){const added=String(prompt('Add new Currency option:')||'').trim().toUpperCase();if(!/^[A-Z]{3}$/.test(added)){currencyInput.value=x.currency;return added&&alert('Enter a three-letter currency code, for example USD.')}const {config,settings}=ttOptionSettings('currency');if(!settings[config.customKey].some(value=>ttOptionToken(value)===ttOptionToken(added)))settings[config.customKey].push(added);ttRestoreOption('currency',added);currencyInput.insertBefore(new Option(added,added),currencyInput.lastElementChild);currencyInput.value=added;audit('Dropdown Options','Currency option added from Customs',added)}x.currency=selectedCurrency();x.saved=false;drawFIs();recalc();ttSetCustomsInlineError(d,x.fiAllocations.some(row=>String(row.currency||'').toUpperCase()!==x.currency)?'Reverse FI allocations in the previous currency before saving the new Customs currency.':'')};
 d.querySelector('#deleteCustomsCurrency')?.addEventListener('click',()=>{const value=selectedCurrency(),remaining=ttActiveOptions('currency').filter(option=>ttOptionToken(option)!==ttOptionToken(value));if(!remaining.length)return alert('At least one Currency option must remain available.');if(!confirm('Remove "'+value+'" from future Currency dropdowns? Existing saved documents keep their value.'))return;const {config,settings}=ttOptionSettings('currency');if(!settings[config.removedKey].some(item=>ttOptionToken(item)===ttOptionToken(value)))settings[config.removedKey].push(value);settings[config.customKey]=settings[config.customKey].filter(item=>ttOptionToken(item)!==ttOptionToken(value));x.currency=remaining[0];x.rate=num(rateInput.value);x.importerChoice=d.querySelector('#cuImporterChoice').value;x.exporter=d.querySelector('#cuExporter')?.value||x.exporter;x.saved=false;audit('Dropdown Options','Currency option removed from Customs',value);save();renderShipmentWorkspace()});
 rateInput.oninput=recalc;if(isTG)payment.onchange=()=>{x.customsPaymentCode=payment.selectedOptions[0]?.dataset.code||'CAD100';x.paymentTerms=ttDirectCustomsPaymentLabel(x.customsPaymentCode);recalc()};
